//! Experimental, private transfer of a computed layout between fresh instances.
//! Only decode data generated by a trusted layout producer from the same document,
//! version, options and build-time font catalog. This is not a public input format.
use crate::{DocLayout, Page};
use std::io::{self, Write};

const MAGIC: &[u8] = b"FVLW\x01";
pub const MAX_WIRE_BYTES: usize = 16 * 1024 * 1024;

struct Bounded(Vec<u8>);
impl Write for Bounded {
    fn write(&mut self, input: &[u8]) -> io::Result<usize> {
        if input.len() > MAX_WIRE_BYTES.saturating_sub(self.0.len()) {
            return Err(io::Error::other("Layout exceeds wire limit"));
        }
        self.0.extend_from_slice(input);
        Ok(input.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

pub fn encode(layout: &DocLayout) -> Result<Vec<u8>, serde_json::Error> {
    let mut writer = Bounded(MAGIC.to_vec());
    serde_json::to_writer(&mut writer, &layout.pages)?;
    Ok(writer.0)
}

pub fn decode(input: &[u8]) -> Result<DocLayout, serde_json::Error> {
    if input.len() > MAX_WIRE_BYTES {
        return Err(serde_json::Error::io(io::Error::other("Layout exceeds wire limit")));
    }
    let json = input.strip_prefix(MAGIC).ok_or_else(|| serde_json::Error::io(io::Error::other("Invalid layout version")))?;
    let pages: Vec<Page> = serde_json::from_slice(json)?;
    let index = crate::pass::index_lines(&pages);
    Ok(DocLayout { pages, index, ..Default::default() })
}

// A process-local FaceRef is never sent over the boundary. Only static build-time
// font identities are permitted; missing or noncanonical keys are errors.
pub(crate) mod face {
    use serde::{Deserialize, Deserializer, Serialize, Serializer};
    use wordcraft_fonts::{FaceRef, FontDb, StaticFaceKey};

    pub fn serialize<S: Serializer>(f: &FaceRef, s: S) -> Result<S::Ok, S::Error> {
        let k = f.static_face_key().ok_or_else(|| serde::ser::Error::custom("Non-static font in layout"))?;
        (k.sha256(), k.index(), k.axes()).serialize(s)
    }
    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<FaceRef, D::Error> {
        let (digest, index, axes): ([u8; 32], u32, Vec<([u8; 4], u32)>) = Deserialize::deserialize(d)?;
        if axes.len() > 64 {
            return Err(serde::de::Error::custom("Too many variation axes"));
        }
        let coords: Vec<_> = axes.iter().map(|(tag, bits)| (*tag, f32::from_bits(*bits))).collect();
        let key = StaticFaceKey::new(digest, index, &coords)
            .filter(|key| key.axes() == axes.as_slice())
            .ok_or_else(|| serde::de::Error::custom("Invalid font identity"))?;
        let f = FontDb::global().static_face_by_key(&key).ok_or_else(|| serde::de::Error::custom("Unknown static font identity"))?;
        Ok(FaceRef::of(&f))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use wordcraft_fonts::{FaceRef, FontDb};

    #[derive(serde::Serialize, serde::Deserialize)]
    struct Ref(#[serde(with = "super::face")] FaceRef);

    #[test]
    fn unknown_or_noncanonical_static_face_key_is_rejected() {
        let font = FontDb::global().face("Source Sans 3", "Regular");
        let encoded = serde_json::to_vec(&Ref(FaceRef::of(&font))).unwrap();
        let decoded: Ref = serde_json::from_slice(&encoded).unwrap();
        assert_eq!(decoded.0.id(), font.id());
        let wrong = serde_json::to_vec(&([0u8; 32], 0u32, Vec::<([u8; 4], u32)>::new())).unwrap();
        assert!(serde_json::from_slice::<Ref>(&wrong).is_err());
        let key = font.static_face_key().unwrap();
        let noncanonical = serde_json::to_vec(&(key.sha256(), key.index(), vec![(*b"wght", (-0.0f32).to_bits())])).unwrap();
        assert!(serde_json::from_slice::<Ref>(&noncanonical).is_err());
    }

    #[test]
    fn writer_enforces_limit_before_extending() {
        let mut writer = Bounded(vec![0; MAX_WIRE_BYTES - 1]);
        assert!(writer.write_all(&[1, 2]).is_err());
        assert_eq!(writer.0.len(), MAX_WIRE_BYTES - 1);
        writer.write_all(&[3]).unwrap();
        assert_eq!(writer.0.len(), MAX_WIRE_BYTES);
    }
}
